export const KINDS = Object.freeze(['mob','boss','myth','fauna','npc']);
export function findCreature(id) { return BY_ID[id] ?? null; }
export function queryCreatures({ biome = '', kind = '', q = '' } = {}) {
  const term = q.trim().toLowerCase();
  return CREATURES.filter(c => (!biome || c.biome === biome) && (!kind || c.kind === kind) && (!term || `${c.id} ${c.kk} ${c.ru} ${c.role}`.toLowerCase().includes(term)));
}
